import{_ as a,o as t,c as o,l as i,t as s,N as n}from"./chunks/framework.Bbd9fWQx.js";const b=JSON.parse('{"title":"git-unpack-objects | x-cmd man (git man1) | Unpack objects from a packed archive","titleTemplate":false,"description":"x-cmd man (git man1 Manual Page) | git-unpack-objects - Unpack objects from a packed archive","frontmatter":{"pageClass":"x-man","head":[["meta",{"name":"og:title","content":"git-unpack-objects | x-cmd man (git man1) | Unpack objects from a packed archive"}],["meta",{"name":"og:description","content":"x-cmd man (git man1 Manual Page) | git-unpack-objects - Unpack objects from a packed archive"}]]},"headers":[],"params":{"isMan":true,"man":"git-unpack-objects","category":"git man1","desc":"Unpack objects from a packed archive"},"relativePath":"git/man1/git-unpack-objects.md","filePath":"git/man1/git-unpack-objects.md"}'),c={name:"git/man1/git-unpack-objects.md"},p={class:"visually-hidden"},r=n('<h2 id="name" tabindex="-1">NAME <a class="header-anchor" href="#name" aria-label="Permalink to &quot;NAME&quot;">​</a></h2><p>git-unpack-objects - Unpack objects from a packed archive</p><h2 id="synopsis" tabindex="-1">SYNOPSIS <a class="header-anchor" href="#synopsis" aria-label="Permalink to &quot;SYNOPSIS&quot;">​</a></h2><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> unpack-objects</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [-n] [-q] [-r] [--strict]</span></span></code></pre></div><h2 id="description" tabindex="-1">DESCRIPTION <a class="header-anchor" href="#description" aria-label="Permalink to &quot;DESCRIPTION&quot;">​</a></h2><p>Read a packed archive (.pack) from the standard input, expanding the objects contained within and writing them into the repository in &quot;loose&quot; (one object per file) format.</p><p>Objects that already exist in the repository will <strong>not</strong> be unpacked from the packfile. Therefore, nothing will be unpacked if you use this command on a packfile that exists within the target repository.</p><p>See <strong>git-repack</strong>(1) for options to generate new packs and replace existing ones.</p><h2 id="options" tabindex="-1">OPTIONS <a class="header-anchor" href="#options" aria-label="Permalink to &quot;OPTIONS&quot;">​</a></h2><p>-n</p><blockquote><p>Dry run. Check the pack file without actually unpacking the objects.</p></blockquote><p>-q</p><blockquote><p>The command usually shows percentage progress. This flag suppresses it.</p></blockquote><p>-r</p><blockquote><p>When unpacking a corrupt packfile, the command dies at the first corruption. This flag tells it to keep going and make the best effort to recover as many objects as possible.</p></blockquote><p>--strict</p><blockquote><p>Don&#39;t write objects with broken content or links.</p></blockquote><p>--max-input-size=&lt;size&gt;</p><blockquote><p>Die, if the pack is larger than &lt;size&gt;.</p></blockquote><h2 id="git" tabindex="-1">GIT <a class="header-anchor" href="#git" aria-label="Permalink to &quot;GIT&quot;">​</a></h2><p>Part of the <strong>git</strong>(1) suite</p>',21);function l(e,h,d,k,g,m){return t(),o("div",null,[i("h1",p,s(e.$params.man),1),r])}const f=a(c,[["render",l]]);export{b as __pageData,f as default};
